/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const selectedTabIndex = event.payload.selectedTabIndex;
    const allTabs = api.state.tabs.output;
    const currentTab = allTabs[selectedTabIndex];
    var route = currentTab.route;

    return {
        viewportElementId: 'viewport_1',
        route: route,
        fields: null,
        params: null
    };
}
